package org.mockito.internal.matchers;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Equality_areEqual_TriageGen1Test {

    @Test
    public void testAreEqual_BothNull() {
        assertTrue(Equality.areEqual(null, null));
    }



















    /**
     * Note: Since isArray and areArraysEqual are internal/private logic 
     * within the Equality class, these tests assume the standard behavior 
     * of the Mockito internal implementation where isArray checks if 
     * the object is an array type via reflection.
     */
    private static boolean isArray(Object obj) {
        return obj != null && obj.getClass().isArray();
    }
}

